(function(root,factory){const api=factory();if(typeof module==='object'&&module.exports)module.exports=api;else root.EmberLifetime=api})(typeof window==='object'?window:globalThis,()=>{
 const ranges={size:[0,5],opacity:[0,1]};
 function validate(curves){if(curves===undefined)return;if(!curves||typeof curves!=='object'||Array.isArray(curves)||Object.keys(curves).some(k=>!['size','opacity','color'].includes(k)))throw Error('Invalid lifetime curves');for(const [key,points]of Object.entries(curves)){if(!Array.isArray(points)||points.length<2||points.length>8)throw Error('Use two to eight lifetime stops');let previous=-1;for(const p of points){if(!p||!Number.isFinite(p.time)||p.time<0||p.time>1||p.time<=previous)throw Error('Lifetime stops must have different, increasing ages');previous=p.time;if(key==='color'?!/^#[0-9a-f]{6}$/i.test(p.value):!Number.isFinite(p.value)||p.value<ranges[key][0]||p.value>ranges[key][1])throw Error('Invalid lifetime '+key);}if(points[0].time!==0||points.at(-1).time!==1)throw Error('Lifetime curves must start at birth and end at death');}}
 function sample(points,t,mix=(a,b,f)=>a+(b-a)*f){t=Math.max(0,Math.min(1,t));for(let i=1;i<points.length;i++)if(t<=points[i].time){const a=points[i-1],b=points[i];return mix(a.value,b.value,(t-a.time)/(b.time-a.time));}return points.at(-1).value;}
 function size(settings,t){return settings.lifetime?.size?sample(settings.lifetime.size,t):1+((settings.endSize??1)-1)*t;}
 function opacity(settings,t){return settings.lifetime?.opacity?sample(settings.lifetime.opacity,t):Math.min(t*8,1)*(1-t*(1-(settings.endOpacity??0)));}
 return {validate,sample,size,opacity};
});
